import { RoutezFeatureModule } from "@_core/_route";
import { Routes } from "@angular/router";
import { CheckIn } from "./check-in/check-in";
import { CheckInAdd } from "./check-in/check-in-add/check-in-add";

export const Routez: Routes = new RoutezFeatureModule(
  'Attendance',
  'feature/attendance',
)
.feature(
  CheckIn,
  CheckInAdd,
  'check-in',
  'Check In'
)
.build();
